message.content:
{
  "candidate_edge_types": [
    {
      "name": "CONFIRMS_PROPOSED_MECHANISM",
      "definition": "An observed result of an experiment performed to evaluate a proposed mechanism provides evidence that the mechanism behaves as hypothesized, validating it for adoption.",
      "source_description": "An experiment or test execution performed to evaluate a proposed mechanism or approach.",
      "target_description": "An observed execution result that provides evidence supporting the proposed mechanism's expected behavior."
    },
    {
      "name": "APPLIES_VALIDATED_RESULT",
      "definition": "A result or finding validated in an earlier execution step is reused as input to produce or modify a target artifact.",
      "source_description": "A result or finding that was validated or confirmed in an earlier execution step.",
      "target_description": "An agent action that incorporates the validated result into a target artifact or deliverable."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure identified during an earlier execution step by fixing the condition that caused it.",
      "source_description": "An earlier observed execution failure or error result.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "RESPONDS_TO_FAILED_ATTEMPT_WITH_ALTERNATIVE",
      "definition": "After an execution attempt fails to accomplish its intended goal (no effect, error, or unavailable tool/module), the agent selects a different action to accomplish the same goal by an alternative mechanism.",
      "source_description": "An execution attempt that failed to accomplish its intended goal or produced no usable result.",
      "target_description": "An alternative agent action intended to accomplish the same goal by a different mechanism."
    },
    {
      "name": "DIAGNOSES_CAUSE_OF_FAILURE",
      "definition": "The agent analyzes an observed failure or error result to identify its underlying cause before attempting a remedy.",
      "source_description": "An observed failure or error result from an execution step.",
      "target_description": "An explanatory diagnosis identifying the underlying cause of the observed failure."
    },
    {
      "name": "VERIFIES_REPAIR_OUTCOME",
      "definition": "A subsequent verification execution is performed to check whether an earlier corrective or state-changing action achieved its intended result.",
      "source_description": "An earlier corrective or state-changing action taken to address a failure or produce a required state.",
      "target_description": "A subsequent verification execution that checks the outcome of that action."
    },
    {
      "name": "CONFIRMED_SUCCESS_TRIGGERS_COMPLETION",
      "definition": "A successful verification result confirming the required behavior leads the agent to conclude the task and mark it complete.",
      "source_description": "A successful verification or test result confirming the required behavior.",
      "target_description": "The agent's task-completion decision or action."
    }
  ]
}

